from pathlib import Path
import base64, hashlib, sys

V96_SHA = 'dc0938fa82952e6599b04725f1e397ac1f317a0ddffaefbae204e265171b0a22'
V104_SHA = '78519fbec9086be2c78ef9ac0a10d2f39edc19fd17748286131242b9adcc1a9e'
V122_SHA = 'ae4c0f5a9afabf2e6d668cf0571b41bfe9a52a9179b499a71aeb6b7508ace8f1'
OLD = base64.b64decode('')
NEW = base64.b64decode('')
OVERLAY = base64.b64decode('')

def sha(data): return hashlib.sha256(data).hexdigest()

def build(src, dst):
    data = Path(src).read_bytes()
    if sha(data) != V96_SHA: raise SystemExit(f"v96 sha mismatch: {sha(data)}")
    if data.count(OLD) != 1: raise SystemExit(f"expected one reserve block, got {data.count(OLD)}")
    v104 = data.replace(OLD, NEW, 1)
    if sha(v104) != V104_SHA: raise SystemExit(f"v104 sha mismatch: {sha(v104)}")
    v122 = v104 + OVERLAY
    if sha(v122) != V122_SHA: raise SystemExit(f"v122 sha mismatch: {sha(v122)}")
    Path(dst).write_bytes(v122)
    compile(v122.decode("utf-8"), str(dst), "exec")
    print("v96_sha256", V96_SHA)
    print("v104_sha256", V104_SHA)
    print("v122_sha256", V122_SHA)

if __name__ == "__main__":
    if len(sys.argv) != 3: raise SystemExit("usage: reconstruct_v122_from_v96.py V96 OUT")
    build(sys.argv[1], sys.argv[2])
